    @ParameterizedTest @ValueSource(booleans = {false, true})
    void actualComponentRowsRetainPerRowEventsThroughResidentOrSpilledReplay(boolean spill) {
        List<Statement> data = new ArrayList<>();
        for (int i = 0; i < 12; i++) {
            data.add(NativeCompositeOriginFixture.VF.createStatement(NativeCompositeOriginFixture.iri("long" + i),
                    NativeCompositeOriginFixture.iri("p"), NativeCompositeOriginFixture.VF.createIRI(NativeCompositeOriginFixture.EX + "payload:" + "payload".repeat(2048) + i)));
            if (i % 2 == 0) data.add(NativeCompositeOriginFixture.VF.createStatement(NativeCompositeOriginFixture.iri("long" + i),
                    NativeCompositeOriginFixture.iri("q"), NativeCompositeOriginFixture.iri("keep")));
        }
        var source = source(data);
        TupleExpr root = NativeCompositeOriginFixture.parse(NativeCompositeOriginFixture.PREFIX
                + "SELECT ?s ?o ?v WHERE { ?s ex:p ?o OPTIONAL { ?s ex:q ?v } }");
        List<BindingSet> expected = drain(ordinary(source, true).precompile(root.clone()), EmptyBindingSet.getInstance(), false);
        assertEquals(12, expected.size());
        var compiled = nativeStrategy(source, true).precompile(root);
        var memory = LmdbQueryMemoryManager.createForTesting(4L << 20, 4L << 20);
        var context = new NativeExecutionContext();
        try (context; var ledger = memory.openQuery()) {
            NativeResultRow.Schema replaySchema = new NativeResultRow.Schema("s", "o", "v");
            try (NativeResultReplay replay = new NativeResultReplay(replaySchema,
                    context, context.cancellation(), ledger, spill ? 16_384L : 1L << 20)) {
                try (NativeResultCursor producer = NativeResultSteps.open(compiled, EmptyBindingSet.getInstance())) {
                    replay.retainProducerAuthority(producer);
                    for (NativeResultRow row; (row = producer.next()) != null;) {
                        BindingSet semanticRow = row.toBindingSet();
                        Set<String> names = Set.copyOf(semanticRow.getBindingNames());
                        assertEquals(semanticRow.hasBinding("v") ? Set.of("s", "o", "v") : Set.of("s", "o"), names,
                                "each produced RDF row has only the expected semantic bindings before schema normalization");
                        replay.append(NativeResultRow.fromBindingSet(replaySchema, semanticRow));
                    }
                }
                replay.finish(); assertEquals(spill, replay.spilled());
                for (int pass = 0; pass < 2; pass++) {
                    List<BindingSet> actual = new ArrayList<>();
                    try (NativeResultCursor reader = replay.cursor()) {
                        for (NativeResultRow row; (row = reader.next()) != null;) actual.add(row.toBindingSet());
                    }
                    assertRows(expected, actual);
                }
            }
            assertEquals(0L, ledger.usedBytes());
        }
        assertEquals(source.opened, source.closed);
    }

